import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { seedData } from "./src/seeds" with { type: "ref" };

import { getProducts } from "./src/queries/getProducts" with { type: "ref" };
import { getOrders } from "./src/queries/getOrders" with { type: "ref" };
import { getAlerts } from "./src/queries/getAlerts" with { type: "ref" };
import { getPurchaseOrders } from "./src/queries/getPurchaseOrders" with { type: "ref" };

import { fulfillOrder } from "./src/actions/fulfillOrder" with { type: "ref" };

export default app({
  name: "app",
  title: "Warehouse Tracker",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
    onAuthSucceededRedirectTo: "/",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    query(getProducts, { entities: ["Product", "Supplier"] }),
    query(getOrders, { entities: ["Order", "OrderItem", "Product"] }),
    query(getAlerts, { entities: ["Alert"] }),
    query(getPurchaseOrders, { entities: ["PurchaseOrder", "Supplier", "Product"] }),

    action(fulfillOrder, { entities: ["Order", "OrderItem", "Product", "Alert", "PurchaseOrder", "Supplier"] }),
  ],
});

import { hashPassword } from "wasp/server/auth";

export async function seedData(prisma: any) {
  // 1. Create or upsert the user
  const username = "warehouse_manager";
  const existingUser = await prisma.user.findUnique({
    where: { username },
  });

  if (!existingUser) {
    const hashedPassword = await hashPassword("password123");
    await prisma.user.create({
      data: {
        username,
        password: hashedPassword,
      },
    });
  }

  // 2. Seed Suppliers
  const suppliers = [
    { id: 1, name: "Global Tech Distributors", email: "supply@globaltech.com" },
    { id: 2, name: "Apex Logistics", email: "orders@apexlogistics.com" },
  ];

  for (const supplier of suppliers) {
    await prisma.supplier.upsert({
      where: { id: supplier.id },
      update: {
        name: supplier.name,
        email: supplier.email,
      },
      create: supplier,
    });
  }

  // 3. Seed Products
  const products = [
    {
      id: 1,
      sku: "PROD-001",
      name: "Wireless Mouse",
      stock: 15,
      lowStockThreshold: 10,
      reorderQuantity: 50,
      supplierId: 1,
    },
    {
      id: 2,
      sku: "PROD-002",
      name: "Mechanical Keyboard",
      stock: 8,
      lowStockThreshold: 5,
      reorderQuantity: 20,
      supplierId: 2,
    },
  ];

  for (const product of products) {
    await prisma.product.upsert({
      where: { sku: product.sku },
      update: {
        name: product.name,
        stock: product.stock,
        lowStockThreshold: product.lowStockThreshold,
        reorderQuantity: product.reorderQuantity,
        supplierId: product.supplierId,
      },
      create: product,
    });
  }

  // 4. Seed Orders
  const order1 = await prisma.order.findUnique({ where: { id: 1 } });
  if (!order1) {
    await prisma.order.create({
      data: {
        id: 1,
        customerName: "TechCorp Solutions",
        status: "PENDING",
        orderItems: {
          create: [
            { productId: 1, quantity: 8 },
            { productId: 2, quantity: 2 },
          ],
        },
      },
    });
  }

  const order2 = await prisma.order.findUnique({ where: { id: 2 } });
  if (!order2) {
    await prisma.order.create({
      data: {
        id: 2,
        customerName: "RetailHub",
        status: "PENDING",
        orderItems: {
          create: [
            { productId: 1, quantity: 10 },
            { productId: 2, quantity: 2 },
          ],
        },
      },
    });
  }
}

import { LoginForm } from "wasp/client/auth";
import { Link } from "react-router";

export function LoginPage() {
  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      alignItems: "center",
      height: "100vh",
      backgroundColor: "#f3f4f6",
      fontFamily: "system-ui, sans-serif"
    }}>
      <div style={{
        backgroundColor: "#ffffff",
        padding: "2rem",
        borderRadius: "8px",
        boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)",
        width: "100%",
        maxWidth: "400px"
      }}>
        <h2 style={{ textAlign: "center", marginBottom: "1.5rem", color: "#1f2937" }}>
          Warehouse Login
        </h2>
        <LoginForm />
        <p style={{ marginTop: "1rem", textAlign: "center", fontSize: "0.875rem", color: "#4b5563" }}>
          Don't have an account? <Link to="/signup" style={{ color: "#3b82f6", textDecoration: "none", fontWeight: "bold" }}>Sign up</Link>
        </p>
      </div>
