}

import { SignupForm } from "wasp/client/auth";
import { Link } from "react-router";

export function SignupPage() {
  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      alignItems: "center",
      height: "100vh",
      backgroundColor: "#f3f4f6",
      fontFamily: "system-ui, sans-serif"
    }}>
      <div style={{
        backgroundColor: "#ffffff",
        padding: "2rem",
        borderRadius: "8px",
        boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)",
        width: "100%",
        maxWidth: "400px"
      }}>
        <h2 style={{ textAlign: "center", marginBottom: "1.5rem", color: "#1f2937" }}>
          Warehouse Sign Up
        </h2>
        <SignupForm />
        <p style={{ marginTop: "1rem", textAlign: "center", fontSize: "0.875rem", color: "#4b5563" }}>
          Already have an account? <Link to="/login" style={{ color: "#3b82f6", textDecoration: "none", fontWeight: "bold" }}>Log in</Link>
        </p>
      </div>
    </div>
  );
}

export const getProducts = async (args: any, context: any) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }
  return context.entities.Product.findMany({
    include: {
      supplier: true,
    },
  });
};

export const getOrders = async (args: any, context: any) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }
  return context.entities.Order.findMany({
    include: {
      orderItems: {
        include: {
          product: true,
        },
      },
    },
  });
};

export const getAlerts = async (args: any, context: any) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }
  return context.entities.Alert.findMany({
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getPurchaseOrders = async (args: any, context: any) => {
  if (!context.user) {
    throw new Error("Unauthorized");
  }
  return context.entities.PurchaseOrder.findMany({
    include: {
      supplier: true,
      product: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });
};

import { HttpError } from "wasp/server";
import { prisma } from "wasp/server";

export const fulfillOrder = async (args: { orderId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const { orderId } = args;
  if (orderId === undefined || orderId === null) {
    throw new HttpError(400, "Order ID is required");
  }

  const prismaClient = context.prisma || prisma;

  return await prismaClient.$transaction(async (tx: any) => {
    // 1. Fetch the order with its items
    const order = await tx.order.findUnique({
      where: { id: orderId },
      include: {
        orderItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!order) {
      throw new HttpError(404, `Order with ID ${orderId} not found`);
    }

    if (order.status === "FULFILLED") {
      throw new HttpError(400, `Order ${orderId} is already fulfilled`);
    }

    // 2. Check stock for all items
    for (const item of order.orderItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!product) {
        throw new HttpError(404, `Product with ID ${item.productId} not found`);
      }

      if (product.stock < item.quantity) {
        throw new HttpError(
          400,
          `Insufficient stock for product ${product.name}. Requested: ${item.quantity}, Available: ${product.stock}`
        );
      }
    }

    // 3 & 4. Decrement stock, create alerts and POs
    for (const item of order.orderItems) {
      const product = await tx.product.findUnique({
        where: { id: item.productId },
      });

      const newStock = product.stock - item.quantity;

      // Update product stock
      await tx.product.update({
        where: { id: product.id },
        data: { stock: newStock },
      });

      // Check if stock falls strictly below lowStockThreshold
      if (newStock < product.lowStockThreshold) {
        // Create Alert
        await tx.alert.create({
          data: {
            productId: product.id,
            message: `Low stock alert for ${product.name} (SKU: ${product.sku}). Current stock: ${newStock}.`,
          },
        });

        // Check for existing PO with status "SENT"
        const existingPO = await tx.purchaseOrder.findFirst({
          where: {
            productId: product.id,
            status: "SENT",
          },
        });

        if (!existingPO) {
          await tx.purchaseOrder.create({
            data: {
              supplierId: product.supplierId,
              productId: product.id,
              quantity: product.reorderQuantity,
              status: "SENT",
            },
          });
        }
      }
    }

    // 5. Set order status to FULFILLED
    const updatedOrder = await tx.order.update({
      where: { id: orderId },
      data: { status: "FULFILLED" },
    });

    return updatedOrder;
  });
};

