     * @returns The payload of the JWT token.
     * @throws If the token is invalid or expired.
     */
    validateJWT: async <T>(token: string): Promise<T> => {
      const { payload } = await validateJWT(JWT_ALGORITHM, JWT_SECRET, token);
      return payload as T;
    },
  };
